/**
 * Context window management — the conversation sent to the model cannot grow
 * forever, so this module implements TWO real strategies:
 *
 *  1. Truncation: only the last N messages (MAX_WINDOW_MESSAGES) are sent as
 *     raw turn-by-turn history. Older messages are evicted from the window.
 *
 *  2. Running summary: evicted messages are folded into a rolling summary
 *     (generated by the LLM itself) which is prepended to the system prompt,
 *     so facts from 10+ messages ago survive truncation.
 *
 * Together they form the classic "sliding window + summary" pattern.
 */

import { SYSTEM_PROMPT } from "./systemPrompt.js";

const MAX_WINDOW_MESSAGES = Number(process.env.MAX_WINDOW_MESSAGES) || 12;

/**
 * Given a conversation { history, summary }, return the exact payload to send
 * to Gemini: the system instruction (persona + running summary) and the
 * truncated recent message window.
 */
export function buildRequest({ history, summary }) {
  const start = Math.max(0, history.length - MAX_WINDOW_MESSAGES);
  const window = history.slice(start);
  const evicted = history.slice(0, start);

  let systemInstruction = SYSTEM_PROMPT;
  if (summary) {
    systemInstruction +=
      `\n\n--- RUNNING SUMMARY OF EARLIER CONVERSATION (older turns were truncated, trust this as memory) ---\n${summary}`;
  }

  const contents = window.map((m) => ({
    role: m.role, // "user" | "model" (Gemini's name for assistant)
    parts: [{ text: m.text }],
  }));

  return { systemInstruction, contents, evicted, windowSize: window.length };
}

/**
 * Ask the LLM to compress (oldSummary + evicted messages) into a new running
 * summary. Facts, names, numbers and user preferences must survive.
 */
export async function summarise(evictedMessages, oldSummary, callModel) {
  if (!evictedMessages.length) return oldSummary ?? null;

  const transcript = evictedMessages
    .map((m) => `${m.role === "user" ? "User" : "Kryptix"}: ${m.text}`)
    .join("\n");

  const prompt = `You maintain a running summary of a conversation so an assistant never loses context.

${oldSummary ? `EXISTING SUMMARY:\n${oldSummary}\n` : ""}
NEW MESSAGE(S) TO FOLD IN:
${transcript}

Rewrite the complete summary (existing + new) in <= 120 words. It MUST preserve:
- The user's name and any personal facts, numbers, preferences or requests they stated.
- Topics discussed and any open questions.
Write it as dense bullet points. Output only the summary.`;

  return callModel(prompt);
}
